export function createAudio(){let context,engine,gain,filter,roadGain,enabled=false;return {get enabled(){return enabled;},async toggle(){if(!context){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return false;context=new AC();engine=context.createOscillator();engine.type='sawtooth';filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=200;gain=context.createGain();gain.gain.value=0;engine.connect(filter).connect(gain).connect(context.destination);engine.start();const buffer=context.createBuffer(1,context.sampleRate*2,context.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.25;const noise=context.createBufferSource();noise.buffer=buffer;noise.loop=true;const low=context.createBiquadFilter();low.type='lowpass';low.frequency.value=650;roadGain=context.createGain();roadGain.gain.value=0;noise.connect(low).connect(roadGain).connect(context.destination);noise.start();}await context.resume();enabled=!enabled;return enabled;},update(state,paused){if(!context)return;const t=context.currentTime;engine.frequency.setTargetAtTime(26+state.rpm/65,t,.08);filter.frequency.setTargetAtTime(140+state.throttle*450,t,.1);gain.gain.setTargetAtTime(enabled&&!paused?.012+state.throttle*.023:0,t,.1);roadGain.gain.setTargetAtTime(enabled&&!paused?Math.min(.16,Math.abs(state.speed)*.006):0,t,.15);},click(){if(!enabled||!context)return;const osc=context.createOscillator(),g=context.createGain();osc.frequency.value=800;g.gain.setValueAtTime(.025,context.currentTime);g.gain.exponentialRampToValueAtTime(.0001,context.currentTime+.04);osc.connect(g).connect(context.destination);osc.start();osc.stop(context.currentTime+.05);}};}
